{"content": "`timescale 1ns/1ps
// Exact-chain bench for the R19 CLEAR path.
//
// The two real AHB stages, gpu_accel, its async command FIFO, the blitter,
// geometry/pixel engines and ddr_gpu_arb are used unmodified.  Only the
// external CPU master and the external DDR readiness model live here.
//
// Fault injection is done exclusively on bench connections/inputs:
//   fault 0 : healthy model (seed 1/8 select different clock periods,
//             relative phase and stall phase)
//   fault 1 : hold m_ready low after TARGET completes
//   fault 2 : hold m_wr_ready low after TARGET completes
//   fault 3 : split the arbiter b_ready from the GPU ready input, so the
//             arbiter still accepts native writes while the GPU never sees
//             acceptance feedback
//   fault 4 : TB-driven reset while a CLEAR native write is pending with
//             native readiness withheld; then fresh TARGET/CLEAR recovery
//   fault 5 : the protected native_monitor changes only its observation of
//             the first accepted write into a READ.  Bench stimuli are
//             unchanged; this proves monitor sensitivity, not DUT behaviour.
//
// No RTL file is edited.  All prints are simulation observations only.
module bench;
    // ------------------------------------------------------------------
    // Run configuration and seed-dependent clocks
    // ------------------------------------------------------------------
    integer seed = 1;
    integer fault = 0;
    integer hclk_half = 6;       // ns, half period
    integer memclk_half = 7;     // ns, half period
    integer memclk_phase = 1;    // ns before the first mem_clk edge
    integer stall_offset = 0;    // mem_clk stall-pattern phase

    initial begin
        $value$plusargs("seed=%d", seed);
        $value$plusargs("fault=%d", fault);
        // Seed 1 and seed 8 deliberately use different periods, relative
        // phase and DDR stall phase; both are legal timing models.
        case (seed)
            8: begin
                hclk_half    = 5;
                memclk_half  = 8;
                memclk_phase = 3;
                stall_offset = 3;
            end
            default: begin
                hclk_half    = 6;
                memclk_half  = 7;
                memclk_phase = 1;
                stall_offset = 0;
            end
        endcase
    end

    reg hclk = 0, mem_clk = 0, resetn = 0;

    // The 1 ps settle delay lets the plusarg/period decode above happen
    // before the first generator delay is evaluated.
    initial begin
        #0.001;
        forever #(hclk_half) hclk = ~hclk;
    end
    initial begin
        #0.001;
        #(memclk_phase);
        forever #(memclk_half) mem_clk = ~mem_clk;
    end

    // ------------------------------------------------------------------
    // AHB master and the two real bus stages
    // ------------------------------------------------------------------
    reg hsel = 0, hwrite = 0;
    reg [31:0] haddr = 0, hwdata = 0;
    reg [1:0] htrans = 0;
    wire hready;
    wire [31:0] hrdata;

    wire [1:0] leg_sel, leg_trans;
    wire leg_write, leg_ready;
    wire [31:0] leg_addr, leg_wdata, leg_rdata;

    ahb_exts_bridge bridge(
        .hclk(hclk), .hresetn(resetn),
        .m_hsel(hsel), .m_haddr(haddr), .m_htrans(htrans),
        .m_hwrite(hwrite), .m_hwdata(hwdata),
        .m_hrdata(hrdata), .m_hready(hready),
        .s_hsel(leg_sel), .s_htrans(leg_trans), .s_hwrite(leg_write),
        .s_haddr(leg_addr), .s_hwdata(leg_wdata),
        .s0_hrdata(32'hbad00000), .s0_hready(1'b1),
        .s1_hrdata(leg_rdata), .s1_hready(leg_ready));

    wire bus_sel, bus_write, bus_ready;
    wire [1:0] bus_trans;
    wire [31:0] bus_addr, bus_wdata, bus_rdata;

    video_bus_stage stage(
        .clk(hclk), .resetn(resetn),
        .s_hsel(leg_sel[1]), .s_hwrite(leg_write), .s_htrans(leg_trans),
        .s_haddr(leg_addr), .s_hwdata(leg_wdata),
        .s_hready(leg_ready), .s_hrdata(leg_rdata),
        .m_hsel(bus_sel), .m_hwrite(bus_write), .m_htrans(bus_trans),
        .m_haddr(bus_addr), .m_hwdata(bus_wdata),
        .m_hready(bus_ready), .m_hrdata(bus_rdata));

    reg [2:0] selected = 0;
    always @(posedge hclk)
        if (!resetn) selected <= 0;
        else if (bus_sel) selected <= bus_addr[14:12];

    wire [31:0] gpu_data, debug_data;
    wire gpu_ready, debug_ready, debug_accept;
    wire valid, write;
    wire [28:0] addr;
    wire [255:0] wr_data, debug_state;
    wire [31:0] wr_mask;
    wire [63:0] packet_words;

    assign bus_ready = selected == 1 ? gpu_ready :
                       selected == 5 ? debug_ready : 1'b1;
    assign bus_rdata = selected == 1 ? gpu_data :
                       selected == 5 ? debug_data : 32'hbad00001;

    // ------------------------------------------------------------------
    // Native DDR readiness model and fault switches
    // ------------------------------------------------------------------
    reg arm_m = 0;          // fault 1: withhold m_ready
    reg arm_wr = 0;         // fault 2: withhold m_wr_ready
    reg hold_all = 0;       // fault 4: withhold both before/through reset
    reg suppress_feedback = 0; // fault 3: cut arbiter acceptance -> GPU

    reg [31:0] tick = 0;
    wire [31:0] phase_tick = tick + stall_offset;
    wire mrdy_base = ((phase_tick % 7) != 0) && ((phase_tick % 7) != 1);
    wire mwrdy_base = ((phase_tick % 5) != 0);
    wire mrdy = (hold_all || ((fault == 1) && arm_m)) ? 1'b0 : mrdy_base;
    wire mwrdy = (hold_all || ((fault == 2) && arm_wr)) ? 1'b0 : mwrdy_base;

    wire arb_b_ready;
    // Fault 3 intercepts only this connection.  The arbiter keeps seeing its
    // own b_ready and can accept the native write; the GPU does not.
    wire gpu_native_ready =
        ((fault == 3) && suppress_feedback) ? 1'b0 : arb_b_ready;

    wire men, mwen, mwend;
    wire [2:0] mcmd;
    wire [28:0] maddr;
    wire [255:0] mdata;
    wire [31:0] mmask;


    reg [255:0] native_response_data=0;
    reg native_response_valid=0;
    wire [255:0] blit_response_data;
    wire blit_response_valid;
    integer read_accepts=0,read_returns=0,read_delay=0;
    reg [255:0] source_line;
    initial begin
        for(integer k=0;k<8;k=k+1)
            source_line[k*32+:32]=(32'h12000000+4*k)^32'ha5396c17;
    end
    always @(posedge mem_clk)begin
        native_response_valid<=0;
        if(!resetn)begin read_accepts<=0;read_returns<=0;read_delay<=0;end
        else begin
            if(read_delay>0)begin
                read_delay<=read_delay-1;
                if(read_delay==1)begin
                    native_response_data<=source_line;
                    native_response_valid<=1;
                    read_returns<=read_returns+1;
                end
            end
            if(men && mrdy && mcmd==1)begin
                if(read_accepts!=0 || maddr!==29'h04800000 || mwen)
                    $fatal(1,"COPY_BAD_READ_OR_DUPLICATE");
                read_accepts<=read_accepts+1;read_delay<=5;
            end
            if(men && mrdy && mcmd!=0 && mcmd!=1)$fatal(1,"COPY_BAD_COMMAND");
            if(mwen && !(men && mrdy && mwrdy && mcmd==0))
                $fatal(1,"COPY_UNPAIRED_WRITE");
        end
    end

    gpu_accel #(.FONT_FILE("font8x16.hex")) gpu(
        .hclk(hclk), .hresetn(resetn), .mem_clk(mem_clk),
        .hsel(bus_sel && bus_addr[14:12] == 1), .hwrite(bus_write),
        .haddr(bus_addr), .hwdata(bus_wdata), .htrans(bus_trans),
        .hrdata(gpu_data), .hready(gpu_ready),
        .valid(valid), .write(write), .addr(addr),
        .wr_data(wr_data), .wr_mask(wr_mask),
        .ready(gpu_native_ready), .rd_data(blit_response_data), .rd_valid(blit_response_valid),
        .debug_state(debug_state), .debug_accept(debug_accept),
        .observe_packet_words(packet_words));

    neo_gpu_debug debug_port(
        .hclk(hclk), .resetn(resetn), .mem_clk(mem_clk),
        .hsel(bus_sel && bus_addr[14:12] == 5), .hwrite(bus_write),
        .htrans(bus_trans), .haddr(bus_addr), .hwdata(bus_wdata),
        .hrdata(debug_data), .hready(debug_ready),
        .host_accept(debug_accept), .live(debug_state),
        .observe_packet_words(packet_words));

    ddr_gpu_arb arb(
        .clk(mem_clk), .rst_n(resetn),
        .c_en(1'b0), .c_cmd(3'd0), .c_addr(29'd0), .c_ready(),
        .c_wr_en(1'b0), .c_wr_end(1'b0), .c_wr_data(256'd0),
        .c_wr_mask(32'hffffffff), .c_wr_ready(), .c_rd_data(),
        .c_rd_valid(), .c_rd_end(),
        .g_valid(1'b0), .g_addr(29'd0), .g_ready(), .g_data(),
        .g_data_valid(),
        .b_valid(valid), .b_write(write), .b_addr(addr),
        .b_wr_data(wr_data), .b_wr_mask(wr_mask),
        .b_ready(arb_b_ready), .b_rd_data(blit_response_data), .b_rd_valid(blit_response_valid),
        .m_en(men), .m_cmd(mcmd), .m_addr(maddr),
        .m_ready(mrdy), .m_wr_en(mwen), .m_wr_end(mwend),
        .m_wr_data(mdata), .m_wr_mask(mmask),
        .m_wr_ready(mwrdy), .m_rd_data(native_response_data), .m_rd_valid(native_response_valid),
        .m_rd_end(native_response_valid));


    integer received=0, native_requests=0;
    reg [31:0] value;
    reg [31:0] words[0:23];
    integer injection=0;
    initial $value$plusargs("injection=%d",injection);
    // Protected expected stream, independent of model-owned stimulus.
    initial begin
      words[0]=32'h16000000; words[1]=32'h12000020;
      words[2]=32'h12000040; words[3]=32'h00100001;
      words[4]=32'h00200020; words[5]=0; words[6]=0; words[7]=0;
      words[8]=32'h1c000000; words[9]=0; words[10]=32'h6b4d;
      words[11]=0; words[12]=0; words[13]=32'h00100001; words[14]=0; words[15]=0;
      words[16]=32'h1d000000; words[17]=32'h12000000; words[18]=32'h00100001;
      words[19]=32'h20; words[20]=0; words[21]=0; words[22]=0; words[23]=0;
    end
    always @(posedge mem_clk) if(resetn)begin
      if(valid || men || mwen) native_requests<=native_requests+1;
      if(gpu.command_we)begin
        if(received>=24 || gpu.queue_data!==words[received])$fatal(1,"payload order");
        received<=received+1;
      end
    end
    // Deliberate logical counterexamples, not inferred hardware causes.
    // Inject after stable completion, before the next command reaches pixel.
    task automatic inject_after_target;
      if(injection==1)force gpu.u_v1.u_pixels.target_valid=1'b0;
    endtask
    task automatic inject_after_clear;
      if(injection==2)force gpu.u_v1.u_pixels.copy_bad=1'b1;
      if(injection==3)force gpu.u_v1.u_pixels.target_valid=1'b0;
    endtask
    task automatic access(input bit wr,input[31:0] address,input[31:0] data,output[31:0] result);
      integer guard;
      begin
        guard=0;@(negedge hclk);
        while(!hready)begin
          guard=guard+1;if(guard>256)$fatal(1,"AHB ready deadline");@(negedge hclk);
        end
        hsel=1;htrans=2;hwrite=wr;haddr=address;
        @(negedge hclk);hsel=0;htrans=0;hwdata=data;guard=0;
        do begin
          @(negedge hclk);guard=guard+1;if(guard>256)$fatal(1,"AHB response deadline");
        end while(!hready);
        result=hrdata;hwdata=0;hwrite=0;
      end
    endtask
    task automatic send_packet(input integer first);
      for(integer i=first;i<first+8;i++)access(1,32'he9001010,words[i],value);
    endtask
    task automatic observe(input integer want, output integer rejects);
      integer polls;reg[31:0] done_count,status;
      begin
        polls=0;done_count=0;status=1;
        while((done_count!=want || status!=0) && polls<400)begin
          access(0,32'he9001008,0,done_count);
          access(0,32'he9001004,0,status);polls++;
        end
        if(done_count!=want || status!=0)$fatal(1,"completion deadline");
        access(0,32'he9001034,0,value);rejects=value;
        if(native_requests!=0)$fatal(1,"unexpected native request");
      end
    endtask
    integer observed_clear=-1,observed_copy=-1;
    task automatic finish_check;
      integer rejects,want_done,want_words;
      begin
        want_done=injection==1?2:3;want_words=injection==1?16:24;
        observe(want_done,rejects);
        repeat(40)@(negedge hclk);
        if(received!=want_words || native_requests!=0)$fatal(1,"final footprint");
        if(observed_clear!=(injection==1?1:0))$fatal(1,"clear observation");
        if(observed_copy!=(injection==1?-1:(injection==0?0:1)))$fatal(1,"copy observation");
        $display("SEQUENCE_RESULT injection=%0d clear_reject=%0d copy_reject=%0d done=%0d words=%0d native=%0d",
          injection,observed_clear,observed_copy,want_done,received,native_requests);
        $finish;
      end
    endtask
    `include "scenario.svh"
    initial begin #400000;$fatal(1,"global deadline");end
endmodule
"}

{"content": "// GPU V1 extended RGB565 pipeline. New opcodes 22..30; legacy 1..21 unchanged.
// Targets and textures use byte addresses; native DDR uses aligned word addresses.
`default_nettype none
module gpu_v1(
    input wire [3:0] child_resetn,
    input wire clk,rst,start,
    input wire [255:0] command,
    output reg done,
    output wire busy,
    output wire [31:0] observe_packet_word0,
    output wire target_config_valid,material_config_valid,
    output reg [31:0] rejected,fragments,passed,
    output wire [31:0] texture_hits,texture_misses,
    output wire valid,write,
    output wire [28:0] addr,
    output wire [255:0] wr_data,
    output wire [31:0] wr_mask,
    input wire ready,rd_valid,
    input wire [255:0] rd_data
);
    localparam IDLE=0,BAD=1,FINISH=2,TARGET_CHECK=3,TEX_CHECK=4,
      TRI_START=5,TRI_BOOT=6,TRI_WAIT=7,SPAN_CLIP=8,ROW_ADDR=9,
      PLANE_MUL=10,PLANE_SUM=11,PLANE_LOAD=12,CHUNK=13,COLOR_REQ=14,
      COLOR_WAIT=15,Z_REQ=16,Z_WAIT=17,PIX_BEGIN=18,PIX_ADDR=19,
      PIX_TEX=20,PIX_UNPACK=21,PIX_MOD=22,PIX_FOG=23,PIX_FOG_MIX=24,
      PIX_BLEND=25,PIX_STORE=26,PIX_NEXT=27,COLOR_WRITE=28,
      COLOR_SENT=29,Z_WRITE=30,Z_SENT=31,ADVANCE=32,RECT_SETUP=33,
      RECT_ROW=34,RECT_CHUNK=35,RECT_COLOR=36,RECT_CSENT=37,
      RECT_Z=38,RECT_ZSENT=39,RECT_NEXT=40,COPY_START=41,COPY_WAIT=42,RECT_BOUNDS=43,RECT_CLIP=44,DECODE=45,TARGET_WAIT=46,TEX_WAIT=47,
      DECODE_WAIT=48,TARGET_VALIDATE=49,TEX_VALIDATE=50,SPAN_BOUNDS=51,
      PIX_LOD=52,PIX_OFFSET=53,PIX_FETCH=54,PIX_OPAQUE=55,DECODE_PIPE=56,TARGET_PIPE=57;
    reg [57:0] state;
    assign busy=!state[IDLE];
    // Gowin 1.9.12 can absorb consecutive, independently enabled command
    // registers into a DSP C pipeline with the enables reversed. This affects
    // COPY's source base and TARGET's depth range, so preserve the packet
    // boundary in fabric (SUG550 section 4.3/5.12).
    // See TESTS/test_gpu_copy_dsp.py for the primitive-level reproduction.
    reg [255:0] packet /* synthesis syn_preserve=1 */;
    assign observe_packet_word0=packet[31:0];
    wire [31:0] w0=packet[31:0],w1=packet[63:32],w2=packet[95:64],w3=packet[127:96],
        w4=packet[159:128],w5=packet[191:160],w6=packet[223:192],w7=packet[255:224];
    reg target_valid,material_valid,texture_valid,fast_shade,opaque_shade;
    assign target_config_valid=target_valid;
    assign material_config_valid=material_valid;
    reg [29:0] color_base,z_base,texture_base;
    reg [15:0] width,height,color_stride,z_stride,tex_width,tex_height,tex_stride;
    reg [15:0] left,top,right,bottom;
    reg [7:0] flags;
    reg [8:0] alpha,tint_r,tint_g,tint_b;
    reg [15:0] solid,fog_color,fog_near;
    reg [24:0] fog_scale;
    reg tex_argb;
    reg [1:0] mode_u,mode_v;
    reg [3:0] mip_level;
    reg [6:0] plane_valid;
    reg signed [47:0] origins[0:6];
    reg signed [31:0] dx[0:6],dy[0:6];
    reg signed [48:0] value[0:6];
    reg [2:0] plane_index;
    reg signed [48:0] product_x,product_y,plane_sum;
    reg [10:0] px,span_left;
    reg [9:0] py;
    reg [4:0] chunk_count,chunk_left;
    reg [3:0] lane;
    reg [31:0] color_row,z_row;
    reg [28:0] color_addr,z_addr;
    reg [255:0] color_buf,z_buf;
    wire [31:0] pixel_mask;
    reg [15:0] pixel_written /* synthesis syn_preserve=1 */;
    wire [15:0] pixel_written_next /* synthesis syn_keep=1 */;
    wire pixel_commit=!color_load && pixel_visible &&
        (state[PIX_STORE] || state[PIX_OPAQUE]);
    genvar mask_lane;
    generate for(mask_lane=0;mask_lane<16;mask_lane=mask_lane+1)begin: mask_data
        assign pixel_written_next[mask_lane]=!rst && !state[CHUNK] &&
            (pixel_written[mask_lane] || (pixel_commit && lane==mask_lane));
        assign pixel_mask[mask_lane*2+:2]={2{!pixel_written[mask_lane]}};
    end endgenerate
    always @(posedge clk)pixel_written<=pixel_written_next;
    // Track whether this chunk contains a stored pixel. Do not reduce the
    // 32-bit byte mask in the wide native-request enable path.
    reg chunk_dirty;
    reg native_valid,native_write;
    reg [28:0] native_addr;
    reg [255:0] native_data;
    reg [31:0] native_mask;
    reg cache_start,cache_invalidate;
    reg [29:0] cache_address;
    wire cache_busy,cache_done,cache_valid;
    wire [28:0] cache_addr;
    wire [15:0] cached_texel;
    // Only the pixel texture state owns this client, after color/Z replies drain.
    wire copy_done,copy_bad,copy_valid,copy_write;
    wire [28:0] copy_addr;
    wire [255:0] copy_data;
    wire [31:0] copy_mask;
    gpu_copy565 u_copy(.clk(clk),.rst(!child_resetn[0]),.start(state[COPY_START]),.command(packet),
        .dst_base(color_base),.dst_stride(color_stride),.dst_height(height),
        .clip_l(left),.clip_t(top),.clip_r(right),.clip_b(bottom),
        .done(copy_done),.bad(copy_bad),.valid(copy_valid),.write(copy_write),
        .addr(copy_addr),.wr_data(copy_data),.wr_mask(copy_mask),
        .ready(ready && state[COPY_WAIT]),.rd_valid(rd_valid && state[COPY_WAIT]),.rd_data(rd_data));
    assign valid=native_valid || cache_valid || copy_valid;
    // Les multiplexeurs de sortie (adresse, 256 bits de données, masque : plus de 300 entrées) sont
    // commandés par copy_sel, quatre copies d'un bit de phase (COPY_START/COPY_WAIT) qui couvre tous
    // les cycles où copy_valid peut valoir 1, plutôt que par copy_valid lui-même : ce registre du
    // moteur de copie, à 305 destinations, faisait un fil de 5,7 ns (r621). Hors de ces cycles, valid
    // vaut 0 et la valeur des bus est sans effet ; les transactions DDR sont identiques.
    reg [3:0] copy_sel /* synthesis syn_preserve=1 */;
    always @(posedge clk) copy_sel<={4{state[COPY_START] || state[COPY_WAIT]}};
    assign write=copy_sel[0] ? copy_write:native_valid && native_write;
    assign addr=copy_sel[0] ? copy_addr:cache_valid ? cache_addr:native_addr;
    assign wr_data={copy_sel[2] ? copy_data[255:128]:native_data[255:128],copy_sel[1] ? copy_data[127:0]:native_data[127:0]};
    assign wr_mask=copy_sel[3] ? copy_mask:native_mask;
    gpu_texture_cache u_cache(.clk(clk),.rst(!child_resetn[1]),.invalidate(cache_invalidate),.start(cache_start),
        .byte_address(cache_address),.busy(cache_busy),.done(cache_done),.texel(cached_texel),
        .hits(texture_hits),.misses(texture_misses),.valid(cache_valid),.addr(cache_addr),
        .ready(ready && !native_valid),.rd_data(rd_data),.rd_valid(rd_valid && state[PIX_TEX]));
    reg [32:0] color_end,z_end,texture_end;
    always @(posedge clk)begin
        color_end<={3'b0,color_base}+color_stride*height;
        z_end<={3'b0,z_base}+z_stride*height;
        texture_end<={3'b0,texture_base}+tex_stride*tex_height;
    end
    wire texture_alias=(texture_base<color_end && color_base<texture_end) ||
                       ((flags[1] || flags[2]) && texture_base<z_end && z_base<texture_end);
    wire need_background=alpha!=256 || flags[5] || (flags[0] && tex_argb);
    // Explicit set/hold removes the wide FSM clock-enable priority cone.
    // All native requests hold VALID until their registered DDR acceptance.
    // These issue/wait states are mutually exclusive in the one-hot machine.
    wire native_issue=(state[COLOR_REQ] && need_background) ||
        (state[Z_REQ] && flags[1]) ||
        (state[COLOR_WRITE] && chunk_dirty) || state[Z_WRITE] ||
        (state[RECT_COLOR] && clear_flags[0]) || (state[RECT_Z] && clear_flags[1]);
    wire native_wait=state[COLOR_WAIT] || state[Z_WAIT] || state[COLOR_SENT] ||
        state[Z_SENT] || state[RECT_CSENT] || state[RECT_ZSENT];
    always @(posedge clk)begin
        if(rst)native_valid<=0;
        else native_valid<=native_issue || (native_valid && native_wait && !ready);
    end
    wire [4:0] room=5'd16-{1'b0,px[3:0]};
    reg triangle_start;
    wire triangle_busy,triangle_valid;
    wire [10:0] triangle_x,triangle_width;
    wire [9:0] triangle_y;
    gpu_triangle #(.WIDTH(1024),.HEIGHT(512)) u_triangle(.clk(clk),.rst(!child_resetn[2]),.start(triangle_start),
        .x0(w1[31:16]),.y0(w1[15:0]),.x1(w2[31:16]),.y1(w2[15:0]),
        .x2(w3[31:16]),.y2(w3[15:0]),.busy(triangle_busy),.valid(triangle_valid),
        .ready(state[TRI_WAIT]),.span_x(triangle_x),.span_width(triangle_width),.span_y(triangle_y));
    reg [10:0] unclipped_end;
    reg [10:0] clipped_left,clipped_right;
    always @(posedge clk)begin
        clipped_left<=px<left ? left[10:0]:px;
        clipped_right<=unclipped_end>right ? right[10:0]:unclipped_end;
    end
    // Two rational samples overlap division with texture/shading work.
    reg per_select /* synthesis syn_preserve=1 */;
    reg [1:0] per_ready;
    wire [1:0] per_start,per_done,per_valid;
    wire signed [48:0] per_u[0:1],per_v[0:1];
    wire signed [48:0] twice_u={{16{dx[0][31]}},dx[0],1'b0};
    wire signed [48:0] twice_v={{16{dx[1][31]}},dx[1],1'b0};
    wire signed [48:0] twice_q={{16{dx[2][31]}},dx[2],1'b0};
