// Sequential R19 observation scenario: TARGET, CLEAR(flags=0), empty COPY.
//
// Stimulus is built only from the protected bench word table and helpers.  The
// observed reject values are the CPU-visible CSR at +0x34, not native traffic
// and not the injected forces.  Faults 1/2 only delay readiness; injection 1
// invalidates the target before CLEAR, injections 2/3 perturb the child engine
// after a successful CLEAR.  Those are logical counterexamples.

integer target_reject;

initial begin
    // 8 hclk negedges in reset, release, then 20 negedges of settle time.
    resetn = 1'b0;
    repeat (8) @(negedge hclk);
    resetn = 1'b1;
    repeat (20) @(negedge hclk);

    // Packet 0: TARGET 16x1 packed RGB565, base 0x12000020, stride 32.
    // Completion of TARGET alone proves only that its own validate edge ran.
    send_packet(0);
    observe(1, target_reject);
    if (target_reject != 0) $fatal(1, "target was rejected");
    inject_after_target;

    // Packet 8: CLEAR with flags=0 (neither colour nor depth selected).
    // A rejected CLEAR aborts the remaining submission, as firmware does.
    send_packet(8);
    observe(2, observed_clear);
    if (observed_clear != 0) begin
        finish_check;
    end else begin
        // Packet 16: empty COPY (w6=0) against the still-valid source.
        inject_after_clear;
        send_packet(16);
        observe(3, observed_copy);
        finish_check;
    end
end

